74: function expandGlob(globPattern: string): string[] {
75:     // Only supports a trailing /* — sufficient for this repo.
76:     if (globPattern.endsWith("/*")) {
77:         const parent = resolve(paths.repoRoot, globPattern.slice(0, -2));
78:         if (!existsSync(parent)) {
79:             return [];
80:         }
81: 
82:         return readdirSync(parent, { withFileTypes: true })
83:             .filter((d) => d.isDirectory())
84:             .map((d) => resolve(parent, d.name));
85:     }
86:     // Literal directory.
87:     const literal = resolve(paths.repoRoot, globPattern);
88:     return existsSync(literal) ? [literal] : [];
89: }
