91: function discoverWorkspacePackages(rootPkg: PackageJson): WorkspacePackage[] {
92:     // name → dir for every workspace member.
93:     const wsYaml = readFileSync(resolve(paths.repoRoot, "pnpm-workspace.yaml"), "utf8");
94:     const globs = parseWorkspaceGlobs(wsYaml);
95:     const nameToDir = new Map<string, string>();
96:     for (const globPattern of globs) {
97:         for (const pkgDir of expandGlob(globPattern)) {
98:             const pkgJsonPath = resolve(pkgDir, "package.json");
99:             if (!existsSync(pkgJsonPath)) continue;
100:             const pkgJson = JSON.parse(readFileSync(pkgJsonPath, "utf8")) as PackageJson;
101:             if (pkgJson.name) {
102:                 nameToDir.set(pkgJson.name, pkgDir);
103:             }
104:         }
105:     }
106: 
107:     // Only the root's direct workspace:* deps; transitives resolve from the registry.
108:     const directWorkspaceNames = Object.entries({
109:         ...(rootPkg.dependencies ?? {}),
110:         ...(rootPkg.optionalDependencies ?? {}),
111:     })
112:         .filter(([, v]) => typeof v === "string" && v.startsWith("workspace:"))
113:         .map(([k]) => k);
114: 
115:     const found: WorkspacePackage[] = [];
116:     for (const name of directWorkspaceNames) {
117:         const dir = nameToDir.get(name);
118:         if (!dir) {
119:             throw new Error(`Could not locate workspace package ${name} in pnpm-workspace.yaml globs`);
120:         }
121:         found.push({ name, dir });
122:     }
123:     return found;
124: }
