136:     const optionalDependencies = { ...(rootPkg.optionalDependencies ?? {}) } as Record<string, string>;
137: 
138:     const atlasLocalRange = dependencies["@mongodb-js/atlas-local"] ?? optionalDependencies["@mongodb-js/atlas-local"];
139:     if (!atlasLocalRange) {
